use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::Mutex;
use tokio::task::JoinHandle;
use tokio::time::{Duration, Instant};

#[derive(Clone, Copy)]
pub enum EvictionReason {
    Expired,
    Lru,
    Memory,
}

impl EvictionReason {
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::Expired => "expired",
            Self::Lru => "lru",
            Self::Memory => "memory",
        }
    }
}

struct CacheEntry<V> {
    value: V,
    expires_at: Instant,
    size: usize,
    last_accessed: Instant,
    access_count: u64,
}

pub struct CacheConfig {
    pub max_entries: usize,
    pub default_ttl: Duration,
    pub max_memory_bytes: usize,
    pub eviction_check_interval: Duration,
    pub on_evict: Option<Box<dyn Fn(&str, EvictionReason) + Send + Sync>>,
}

impl Default for CacheConfig {
    fn default() -> Self {
        Self {
            max_entries: 1000,
            default_ttl: Duration::from_secs(60),
            max_memory_bytes: 100 * 1024 * 1024,
            eviction_check_interval: Duration::from_secs(5),
            on_evict: None,
        }
    }
}

#[derive(Debug, Clone, Copy, Default)]
pub struct Stats {
    pub hits: u64,
    pub misses: u64,
    pub evictions: u64,
    pub expirations: u64,
    pub size: usize,
    pub memory: usize,
}

struct Inner<V> {
    entries: HashMap<String, CacheEntry<V>>,
    access_order: Vec<String>,
    current_memory: usize,
    stats: Stats,
}

pub struct LRUCache<V> {
    inner: Arc<Mutex<Inner<V>>>,
    config: Arc<CacheConfig>,
    eviction_handle: Option<JoinHandle<()>>,
}

impl<V: EstimateSize + Send + 'static> LRUCache<V> {
    pub fn new(config: CacheConfig) -> Self {
        let inner = Arc::new(Mutex::new(Inner {
            entries: HashMap::new(),
            access_order: Vec::new(),
            current_memory: 0,
            stats: Stats::default(),
        }));
        Self {
            inner,
            config: Arc::new(config),
            eviction_handle: None,
        }
    }

    pub async fn get(&self, key: &str) -> Option<V>
    where
        V: Clone,
    {
        let mut inner = self.inner.lock().await;
        let now = Instant::now();

        let expired = inner
            .entries
            .get(key)
            .map(|e| now > e.expires_at)
            .unwrap_or(false);

        if expired {
            Self::delete_inner(&self.config, &mut inner, key, EvictionReason::Expired);
            inner.stats.misses += 1;
            return None;
        }

        let entry = inner.entries.get_mut(key)?;
        // Not expired
        entry.last_accessed = now;
        entry.access_count += 1;
        let value = entry.value.clone();
        Self::move_to_front(&mut inner.access_order, key);
        inner.stats.hits += 1;
        Some(value)
    }

    pub async fn put(&self, key: &str, value: V, ttl: Option<Duration>, size: Option<usize>) {
        let mut inner = self.inner.lock().await;
        let size = size.unwrap_or_else(|| value.estimate_size());
        let ttl = ttl.unwrap_or(self.config.default_ttl);
        let now = Instant::now();

        if let Some(old) = inner.entries.get(key) {
            inner.current_memory -= old.size;
        }

        while inner.current_memory + size > self.config.max_memory_bytes
            && !inner.access_order.is_empty()
        {
            Self::evict_lru(&self.config, &mut inner, EvictionReason::Memory);
        }

        while inner.entries.len() >= self.config.max_entries && !inner.access_order.is_empty() {
            Self::evict_lru(&self.config, &mut inner, EvictionReason::Lru);
        }

        let entry = CacheEntry {
            value,
            expires_at: now + ttl,
            size,
            last_accessed: now,
            access_count: 0,
        };

        inner.entries.insert(key.to_owned(), entry);
        inner.current_memory += size;
        Self::move_to_front(&mut inner.access_order, key);
    }

    pub async fn delete(&self, key: &str, reason: EvictionReason) -> bool {
        let mut inner = self.inner.lock().await;
        Self::delete_inner(&self.config, &mut inner, key, reason)
    }

    fn delete_inner(
        config: &CacheConfig,
        inner: &mut Inner<V>,
        key: &str,
        reason: EvictionReason,
    ) -> bool {
        let entry = inner.entries.remove(key);
        let Some(entry) = entry else { return false };
        inner.current_memory -= entry.size;
        inner.access_order.retain(|k| k != key);
        match reason {
            EvictionReason::Expired => inner.stats.expirations += 1,
            _ => inner.stats.evictions += 1,
        }
        if let Some(cb) = &config.on_evict {
            cb(key, reason);
        }
        true
    }

    pub async fn has(&self, key: &str) -> bool {
        let mut inner = self.inner.lock().await;
        let Some(entry) = inner.entries.get(key) else {
            return false;
        };
        if Instant::now() > entry.expires_at {
            Self::delete_inner(&self.config, &mut inner, key, EvictionReason::Expired);
            return false;
        }
        true
    }

    pub async fn size(&self) -> usize {
        self.inner.lock().await.entries.len()
    }

    pub async fn memory_usage(&self) -> usize {
        self.inner.lock().await.current_memory
    }

    pub async fn get_stats(&self) -> Stats {
        let inner = self.inner.lock().await;
        Stats {
            hits: inner.stats.hits,
            misses: inner.stats.misses,
            evictions: inner.stats.evictions,
            expirations: inner.stats.expirations,
            size: inner.entries.len(),
            memory: inner.current_memory,
        }
    }

    pub async fn clear(&self) {
        let mut inner = self.inner.lock().await;
        let keys: Vec<String> = inner.entries.keys().cloned().collect();
        for key in keys {
            Self::delete_inner(&self.config, &mut inner, &key, EvictionReason::Lru);
        }
    }

    pub async fn keys(&self) -> Vec<String> {
        self.inner.lock().await.access_order.clone()
    }

    pub fn start_eviction_loop(&mut self)
    where
        V: Clone,
    {
        if self.eviction_handle.is_some() {
            return;
        }
        let inner = self.inner.clone();
        let config = self.config.clone();
        let interval = config.eviction_check_interval;
        self.eviction_handle = Some(tokio::spawn(async move {
            let mut ticker = tokio::time::interval(interval);
            loop {
                ticker.tick().await;
                let mut guard = inner.lock().await;
                let now = Instant::now();
                let expired: Vec<String> = guard
                    .entries
                    .iter()
                    .filter(|(_, e)| now > e.expires_at)
                    .map(|(k, _)| k.clone())
                    .collect();
                for key in expired {
                    Self::delete_inner(&config, &mut guard, &key, EvictionReason::Expired);
                }
            }
        }));
    }

    pub fn stop_eviction_loop(&mut self) {
        if let Some(handle) = self.eviction_handle.take() {
            handle.abort();
        }
    }

    fn move_to_front(access_order: &mut Vec<String>, key: &str) {
        access_order.retain(|k| k != key);
        access_order.insert(0, key.to_owned());
    }

    fn evict_lru(config: &CacheConfig, inner: &mut Inner<V>, reason: EvictionReason) {
        if let Some(oldest) = inner.access_order.pop() {
            Self::delete_inner(config, inner, &oldest, reason);
        }
    }
}

pub trait EstimateSize {
    fn estimate_size(&self) -> usize;
}

impl EstimateSize for String {
    fn estimate_size(&self) -> usize {
        self.len() * 2
    }
}

impl EstimateSize for &str {
    fn estimate_size(&self) -> usize {
        self.len() * 2
    }
}

impl EstimateSize for i64 {
    fn estimate_size(&self) -> usize {
        8
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_basic_get_put() {
        let cache = LRUCache::<String>::new(CacheConfig {
            max_entries: 3,
            default_ttl: Duration::from_millis(100),
            ..Default::default()
        });
        cache.put("a", "hello".into(), None, None).await;
        assert_eq!(cache.get("a").await, Some("hello".into()));
        assert_eq!(cache.size().await, 1);
    }

    #[tokio::test]
    async fn test_lru_eviction() {
        let cache = LRUCache::<String>::new(CacheConfig {
            max_entries: 3,
            default_ttl: Duration::from_millis(100),
            ..Default::default()
        });
        cache.put("a", "hello".into(), None, None).await;
        cache.put("b", "world".into(), None, None).await;
        cache.put("c", "foo".into(), None, None).await;
        cache.put("d", "bar".into(), None, None).await;
        assert!(!cache.has("a").await, "lru eviction");
        assert!(cache.has("d").await, "newest kept");
    }

    #[tokio::test]
    async fn test_ttl_expiration() {
        let cache = LRUCache::<String>::new(CacheConfig {
            max_entries: 3,
            default_ttl: Duration::from_millis(100),
            ..Default::default()
        });
        cache
            .put("x", "temp".into(), Some(Duration::from_millis(50)), None)
            .await;
        tokio::time::sleep(Duration::from_millis(80)).await;
        assert_eq!(cache.get("x").await, None, "ttl expired");
    }

    #[tokio::test]
    async fn test_access_order() {
        let cache = LRUCache::<String>::new(CacheConfig {
            max_entries: 3,
            default_ttl: Duration::from_secs(60),
            ..Default::default()
        });
        cache.put("1", "one".into(), None, None).await;
        cache.put("2", "two".into(), None, None).await;
        cache.put("3", "three".into(), None, None).await;
        cache.get("1").await; // access '1', making '2' the LRU
        cache.put("4", "four".into(), None, None).await; // should evict '2'
        assert!(!cache.has("2").await, "access order eviction");
        assert!(cache.has("1").await, "accessed item kept");
    }

    #[tokio::test]
    async fn test_stats() {
        let cache = LRUCache::<String>::new(CacheConfig {
            max_entries: 3,
            default_ttl: Duration::from_millis(100),
            ..Default::default()
        });
        cache.put("a", "hello".into(), None, None).await;
        cache.get("a").await; // hit
        cache.get("z").await; // miss
        let stats = cache.get_stats().await;
        assert!(stats.hits > 0, "has hits");
        assert!(stats.misses > 0, "has misses");
    }

    #[tokio::test]
    async fn test_eviction_loop() {
        let mut cache = LRUCache::<String>::new(CacheConfig {
            max_entries: 10,
            default_ttl: Duration::from_millis(50),
            eviction_check_interval: Duration::from_millis(30),
            ..Default::default()
        });
        cache.put("e1", "val1".into(), None, None).await;
        cache.start_eviction_loop();
        tokio::time::sleep(Duration::from_millis(150)).await;
        assert!(!cache.has("e1").await, "eviction loop cleared expired");
        cache.stop_eviction_loop();
    }
}
